test('addLine and removeLine work together', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  let invoice = result.value;

  // Add line
  let updated = addLine(invoice, { sku: 'STICKER', qty: 10 });
  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines.length, 2);
  invoice = updated.value;

  // Add another line
  updated = addLine(invoice, { sku: 'ICON-SET', qty: 5 });
  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines.length, 3);
  invoice = updated.value;

  // Remove middle line
  updated = removeLine(invoice, 'STICKER');
  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines.length, 2);
  assert.equal(updated.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(updated.value.lines[1].sku, 'ICON-SET');
  invoice = updated.value;

  // Increase qty of remaining line
  updated = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines[0].qty, 7);
});

