test('invoiceTotals clamps total to 0', () => {
  // Create invoice with high discount that would make total negative
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-02-15',
    status: 'draft',
    lines: [
      { sku: 'STICKER', name: 'Sticker sheet', qty: 10, unitPrice: 50, vatRate: 21, discountPercent: 100 },
    ],
  };

  const totalsResult = invoiceTotals(invoice);

  assert.equal(totalsResult.ok, true);
  // Subtotal: 10 * 50 = 500
