test('renderInvoiceText formats large amounts with thousand separators', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 10 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // BRAND-BOOK is 245000 cents = €2,450.00
  // 10 * 245000 = 2450000 cents = €24,500.00
  assert.match(text, /10 x Brand guidelines document @ €2,450\.00 = €24,500\.00/);
  assert.match(text, /Total: €24,500\.00/);
});

test('renderInvoiceText preserves order of lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'STICKER', qty: 1 },
      { sku: 'ICON-SET', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  assert.match(lines[2], /Development/);
  assert.match(lines[3], /Sticker/);
  assert.match(lines[4], /Icon set/);
});

test('renderInvoiceText with issued invoice displays number and same content', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, ['INV-2025-0001']);
  assert.equal(issued.ok, true);

  const text = renderInvoiceText(issued.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2025-0002');
  assert.equal(lines[1], 'Northwind Studio');
  assert.match(lines[2], /5 x Development \(hour\) @ €95\.00 = €475\.00/);
  assert.match(lines[3], /Total: €475\.00/);
});

test('renderInvoiceText with different VAT rates shows same unitPrice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 100 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // VAT is not shown in render (it's added later)
  // Just checking unitPrices are displayed correctly
  assert.match(text, /€95\.00/); // DEV-HOUR
  assert.match(text, /€0\.37/); // PRINT-A4 (37 cents)
  assert.match(text, /€600\.00/); // WORKSHOP-DAY
});

test('renderInvoiceText with customer that has special characters', () => {
  const result = createInvoice({
    customerId: 'C-006',
    issueDate: '2025-02-15',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // C-006 is "Marlow \"The Print Shop\"" with quotes
  assert.match(text, /Marlow "The Print Shop"/);
});

test('renderInvoiceText output can be printed', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // Should be a string with newlines
  assert.equal(typeof text, 'string');
  assert.ok(text.includes('\n'));

  // Should have 6 lines: number, customer, 2 items, subtotal, total
  const lines = text.split('\n');
  assert.equal(lines.length, 6);

  // Each line should be non-empty
  for (const line of lines) {
    assert.ok(line.length > 0);
  }
});

test('renderInvoiceText shows discount on line item', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // Should show discount percentage and amount
  assert.match(text, /20% off: −€190\.00/);
});

test('renderInvoiceText shows discount total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 20 },
      { sku: 'STICKER', qty: 100, discountPercent: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // Should have subtotal, discount line, and total
  assert.match(text, /Subtotal: €1,000\.00/);
  assert.match(text, /Discount: −€195\.00/);
  assert.match(text, /Total: €805\.00/);
});

test('renderInvoiceText does not show discount line if no discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // Should not have "Discount:" line
  assert.match(text, /Subtotal: €950\.00/);
  assert.match(text, /Total: €950\.00/);
  assert.ok(!text.includes('Discount:'));
});

test('renderInvoiceText with zero discount percent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // Should not show discount amount on line
  assert.match(text, /€950\.00$/m);
  assert.ok(!text.includes('off'));
});

test('renderInvoiceText with decimal discount percent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // Should show decimal discount percentage
  assert.match(text, /12\.5% off/);
});

test('renderInvoiceText with multiple lines and partial discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 },
      { sku: 'STICKER', qty: 50 }, // no discount
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // First line should show discount
  assert.match(text, /5 x Development \(hour\) @ €95\.00 = €475\.00 \(20% off: −€95\.00\)/);
  // Second line should not show discount on same line
  assert.match(text, /50 x Sticker sheet @ €0\.50 = €25\.00/);
});

